template<class F>void fails(const std::string& code,F fn){try{fn();}catch(const Error& e){require(e.code==code,"Expected "+code+", got "+e.code);return;}throw std::runtime_error("Expected "+code);}
struct Temp {fs::path root=fs::temp_directory_path()/path_from_utf8("cad-capture-"+std::to_string(std::chrono::steady_clock::now().time_since_epoch().count()));Temp(){directory(root);}~Temp(){std::error_code e;fs::remove_all(root,e);}};
Json call(Service& s,const std::string& tool,const Json& args){for(int n=0;;++n){try{return s.call(tool,args);}catch(const Error& e){if(e.code!="workspace_busy"||n==1000)throw;}std::this_thread::sleep_for(std::chrono::milliseconds(2));}}
Json sync(Service& s){return call(s,"cad_viewer",{{"action","sync"},{"view_id","capture"}});}
Json ready(Service& s){for(int n=0;n<10000;++n){auto r=sync(s);if(r.at("state")=="ready")return r;require(r.at("state")=="loading","View must build without failure");std::this_thread::sleep_for(std::chrono::milliseconds(2));}throw std::runtime_error("View timeout");}
Json request(Service& s){for(int n=0;n<1000;++n){auto r=sync(s);if(r.contains("capture_requests")&&!r.at("capture_requests").empty())return r.at("capture_requests")[0];std::this_thread::sleep_for(std::chrono::milliseconds(2));}throw std::runtime_error("No capture request");}
